{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name='SELECT ts.orders_other' GROUP BY ALL",
          "claim": "Order-other's DB client spans ('SELECT ts.orders_other') have p95 about 688 ms in abnormal, versus 0.3 ms in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'abn' src,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT ts.orders_other','POST /api/v1/orderOtherService/orderOther/refresh') GROUP BY ALL ORDER BY span_name, src",
          "claim": "Order-other's refresh endpoint p95 rises from about 3.6 ms to about 832 ms while its DB spans slow by a similar amount."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) avg_v FROM abnormal_metrics WHERE service_name='ts-order-other-service' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY metric",
          "claim": "Order-other container CPU and memory stay low and flat, so no resource saturation explains the slow DB calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_span_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.attr_span_kind='Client' AND c.attr_span_kind='Server' AND p.service_name='ts-admin-order-service' AND c.service_name='ts-order-other-service' GROUP BY ALL",
          "claim": "Admin-order's client calls into order-other take about 420 ms p50 in abnormal, where they were a few ms before."
        }
      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'abn' src,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%adminorder%' GROUP BY ALL ORDER BY span_name, src",
          "claim": "User-facing ui-dashboard admin-order endpoints rise from about 12 ms to about 1,500–3,900 ms p95."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-security-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_span_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.attr_span_kind='Client' AND c.attr_span_kind='Server' AND p.service_name='ts-security-service' AND c.service_name='ts-order-other-service' GROUP BY ALL",
          "claim": "Security-service calls to order-other take about 208 ms p50 in abnormal, slowed by the order-other DB calls."
        }
      ]
    },
    {
      "from": "ts-security-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_span_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.attr_span_kind='Client' AND c.attr_span_kind='Server' AND p.service_name='ts-preserve-service' AND c.service_name='ts-security-service' GROUP BY ALL",
          "claim": "Preserve's calls to security take about 23 ms p50 in abnormal, with security's own time inflated by order-other."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'abn' src,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%preserve%' GROUP BY ALL ORDER BY span_name, src",
          "claim": "User-facing preserve requests at ui-dashboard rise from about 136 ms to about 777 ms p95."
